<?php require_once __DIR__.'/../config/auth.php';require_admin();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kitchen Display</title><link rel="stylesheet" href="../assets/style.css"></head><body class="kitchen"><header class="kitchen-head"><div class="container"><div class="logo">COFFEE<span>KITCHEN</span></div><a href="../admin/" style="color:#fff">Admin</a></div></header><main class="container board"><section class="column"><h2>Ordered</h2><div id="ordered"></div></section><section class="column"><h2>Making</h2><div id="making"></div></section><section class="column"><h2>Done</h2><div id="done"></div></section></main><script>
async function load(){const r=await fetch('../api/orders.php');const d=await r.json();if(!d.success)return;['ordered','making','done'].forEach(s=>document.getElementById(s).innerHTML='');d.orders.forEach(o=>{const el=document.createElement('article');el.className='order-card';const items=o.items.map(i=>`<div class="order-item"><strong>${esc(i.quantity)}x ${esc(i.drink_name)}</strong><div class="milk">${esc(i.milk_type||'')}</div></div>`).join('');let next=o.status==='ordered'?'making':'done';let label=o.status==='ordered'?'START MAKING':'MARK DONE';el.innerHTML=`<div class="order-top"><div class="order-num">#${o.order_number}</div><div class="order-time">${new Date(o.created_at.replace(' ','T')).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})}</div></div>${items}<div class="order-total">$${Number(o.total).toFixed(2)}</div>${o.status!=='done'?`<button class="btn btn-yellow" style="width:100%" onclick="setStatus(${o.id},'${next}')">${label}</button>`:''}`;document.getElementById(o.status).appendChild(el);});}
function esc(v){return String(v).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}async function setStatus(id,status){await fetch('../api/status.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,status})});load()}load();setInterval(load,4000);
</script></body></html>